mapper.select:
/*****************deleteProperty 실행!!!******************/
delete from dental_materials where id=#{id}::int4
RETURNING name

mapper.insert:
/*****************insertProperty 실행!!!******************/
INSERT INTO dental_materials (category, code, name, diameter, length, quantity)
VALUES (#{category},#{code},#{name},#{diameter}::numeric(5,2),#{length}::numeric(5,2),#{quantity}::int4);
